import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"认识运维管理","description":"按运行概览、节点管理、工程部署和运维记录查找任务，理解角色和异步操作结果。","frontmatter":{"title":"认识运维管理","description":"按运行概览、节点管理、工程部署和运维记录查找任务，理解角色和异步操作结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/operations.md","filePath":"zh/使用指南/认识运维管理.md"}'),i={name:"zh/guide/operations.md"};function o(n,t,h,l,s,m){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="认识运维管理" tabindex="-1">认识运维管理 <a class="header-anchor" href="#认识运维管理" aria-label="Permalink to &quot;认识运维管理&quot;">​</a></h1><p>运维管理处理平台的<strong>运行环境、节点、工程部署和运行记录</strong>，与应用开发中的 AI、编辑器和页面预览分开。</p><p>从公共入口登录组织，进入 <strong>“运维管理”</strong>，再通过当前区域名称的下拉菜单切换子模块。</p><h2 id="_1-先确认权限" tabindex="-1">1. 先确认权限 <a class="header-anchor" href="#_1-先确认权限" aria-label="Permalink to &quot;1. 先确认权限&quot;">​</a></h2><p>组织管理员和运维人员可维护运行环境、节点等运维配置。工程人员可按权限查看部署、记录并进行工程部署，但不会因此获得节点接入或运行环境管理权限。</p><p>看不到某个区域时先核对角色。不要为了打开入口共用管理员账号。</p><h2 id="_2-选择要处理的模块" tabindex="-1">2. 选择要处理的模块 <a class="header-anchor" href="#_2-选择要处理的模块" aria-label="Permalink to &quot;2. 选择要处理的模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前界面名称</th><th>对应操作</th></tr></thead><tbody><tr><td>运行概览</td><td><a href="/induframe-docs/zh/guide/runtime-environments.html">管理运行环境</a>：查看状态、关联节点、准备基础服务</td></tr><tr><td>节点管理</td><td><a href="/induframe-docs/zh/guide/runtime-nodes.html">管理运行节点</a>：接入登记、身份核对、心跳、资源和节点关联</td></tr><tr><td>工程部署</td><td><a href="/induframe-docs/zh/guide/deployments.html">创建和管理工程部署</a>：选择工程内容、环境、引擎节点和访问方式</td></tr><tr><td>运维记录</td><td><a href="/induframe-docs/zh/guide/operations-records.html">查看运维记录</a>：查找操作进度、系统事件与执行明细</td></tr></tbody></table><p>运行环境是安排运行资源的范围，节点是实际服务器，工程部署是把某个工程内容放到目标环境运行。三者不是同一个对象。</p><h2 id="_3-第一次部署的顺序" tabindex="-1">3. 第一次部署的顺序 <a class="header-anchor" href="#_3-第一次部署的顺序" aria-label="Permalink to &quot;3. 第一次部署的顺序&quot;">​</a></h2><ol><li>确认平台中心和组织可正常使用。</li><li>核对运行环境，以及所需节点是否已接入、在线并具备运行资格。</li><li>关联节点并准备环境基础服务，等待真实就绪。</li><li>准备工程内容；生产模式需要已有正式发布版本。</li><li>创建工程部署，等待运行状态与健康观测。</li><li>打开实际运行入口，核对页面、身份、采集、计算和报警等业务结果。</li></ol><p>开发预览能打开，不能代替第 2–6 步。多节点登记也不代表所有数据服务已具备高可用能力。</p><h2 id="_4-怎样判断操作完成" tabindex="-1">4. 怎样判断操作完成 <a class="header-anchor" href="#_4-怎样判断操作完成" aria-label="Permalink to &quot;4. 怎样判断操作完成&quot;">​</a></h2><p>“已受理”“执行中”“等待就绪”与“运行中”含义不同。先查看目标对象和运维记录，等到结果明确，再确认实际服务。</p><p>读取失败、指标过期或显示保留上次数据时，不以旧的绿色状态判断当前正常。不反复提交部署、重启或删除来催促任务。</p><p>涉及停止、重新部署、移除节点或删除环境时，先通知受影响人员并安排数据保护。尤其注意基础服务重新部署可能清空数据，详见<a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境说明</a>。</p><p>下一步：<a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境</a> · <a href="/induframe-docs/zh/guide/deployments.html">工程部署</a>。</p>',17)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
